                (), (), 1, 50
            ),
            {"waves": (), "totals": zeroed},
        )
        self.assertEqual(
            BranchStore._build_lifetime_churn_forecast_drift_waves_result(
                SYNTHETIC_SCANS, (), 1, 50
            ),
            {"waves": (), "totals": zeroed},
